import React from 'react';

function RegisterForm() {
    // Dựa trên phần Đăng Ký trong HTML
    return (
        <div className="register-form-wrapper">
            <div className="text-wrapper-9">ĐĂNG KÝ</div>
            <form>
                <p className="text-wrapper-13">Địa chỉ email *</p>
                <div className="rectangle-6"><input type="email" /></div>

                <p className="text-wrapper-15">Một mật khẩu sẽ được gửi đến địa chỉ email của bạn.</p>
                
                <p className="th-ng-tin-c-nh-n-c-a">
                    Thông tin cá nhân của bạn sẽ được sử dụng để tăng trải nghiệm sử dụng website...
                </p>

                <div className="rectangle-11">
                    <button className="text-wrapper-16">Đăng Ký</button>
                </div>
            </form>
        </div>
    );
}

export default RegisterForm;
